<?php
declare(strict_types=1);
function ksCetakSuite(KsSuite $s):void{
 $s->t->group='Cetak R05 · kop, konteks dan judul PDF';
 $periode='awal=2020-01-01&akhir=2199-12-31';$titles=[];
 $map=['riwayat'=>'Laporan Riwayat Servis','pendapatan'=>'Laporan Penerimaan Pembayaran','pemakaian'=>'Laporan Pemakaian Suku Cadang','stok'=>'Laporan Stok di Bawah Minimum'];
 foreach($map as $key=>$title)$s->test('Judul, kop dan metadata laporan '.$key,function()use($s,$key,$title,$periode,&$titles){$r=$s->c('owner')->get('panel/laporan.php?jenis='.$key.'&'.$periode);$s->ok($r);preg_match('~<title>(.*?)</title>~s',$r['body'],$m);ksAssert(str_contains($m[1]??'',$title));$titles[]=$m[1];ksAssert(str_contains($r['body'],'class="ks-cetak-kop"')&&str_contains($r['body'],'Waktu cetak')&&str_contains($r['body'],'Dicetak oleh'));ksAssert(str_contains($r['body'],'logo/kalawa-service-logo.svg')&&str_contains($r['body'],'Tel. '));ksAssert(str_contains($r['body'],'class="ks-cetak-contacts"'));});
 $s->test('Judul empat jenis laporan saling berbeda',fn()=>ksAssert(count(array_unique($titles))===4));
 foreach(['admin1','cash1','stock1'] as $role)$s->test('Kop cabang mengikuti role '.$role,function()use($s,$role,$periode){$r=$s->c($role)->get('panel/laporan.php?jenis=stok&'.$periode);$s->ok($r);preg_match('~<div class="ks-cetak-contacts">(.*?)</div>\s*</div>~s',$r['body'],$m);ksAssert(str_contains($m[1]??'','CBG001')&&!str_contains($m[1]??'','CBG002'),'Alamat cabang lain masuk ke kop');});
 $s->test('Filter cabang Owner mengubah nama dan alamat kop',function()use($s,$periode){$r=$s->c('owner')->get('panel/laporan.php?jenis=stok&cabang=CBG002&'.$periode);$s->ok($r);preg_match('~<div class="ks-cetak-contacts">(.*?)</div>\s*</div>~s',$r['body'],$m);ksAssert(str_contains($m[1]??'','CBG002')&&!str_contains($m[1]??'','CBG001'));});
 $s->test('Laporan stok tidak mengklaim periode transaksi',function()use($s,$periode){$r=$s->c('owner')->get('panel/laporan.php?jenis=stok&'.$periode);ksAssert(str_contains($r['body'],'Posisi data')&&!str_contains($r['body'],'<dt>Periode</dt>'));});
 $s->test('Riwayat mencetak seluruh baris yang dimuat dari halaman kedua',function()use($s,$periode){$r=$s->c('audit')->get('panel/laporan.php?jenis=riwayat&hal_laporan=2&'.$periode);$s->ok($r);ksAssert(str_contains($r['body'],'ks-report-paged-out')&&str_contains($r['body'],'ks-cetak-document'));});
 $s->test('Laporan invalid tidak menghasilkan kop dokumen sukses',function()use($s){$r=$s->c('owner')->get('panel/laporan.php?jenis=riwayat&awal=2026-12-01&akhir=2026-01-01');$s->ok($r,422);ksAssert(!str_contains($r['body'],'class="ks-cetak-kop"'));});
 $paid=(string)ksOne($s->db,"SELECT p.no_work_order FROM pembayaran p JOIN work_order w ON w.no_work_order=p.no_work_order WHERE p.status_pembayaran='LUNAS' AND w.kode_cabang='CBG001' ORDER BY p.no_work_order LIMIT 1");
 $s->test('Bukti pembayaran memakai nomor WO dan judul khusus',function()use($s,$paid){ksAssert($paid!=='','Fixture pembayaran lunas tidak tersedia');$r=$s->c('cash1')->get('panel/pembayaran.php?lihat='.rawurlencode($paid));$s->ok($r);preg_match('~<title>(.*?)</title>~s',$r['body'],$m);ksAssert(str_contains($m[1]??'','Bukti Pembayaran Servis')&&str_contains($m[1],$paid));ksAssert(str_contains($r['body'],'id="rincian-pembayaran"'));});
 $unpaid=(string)ksOne($s->db,"SELECT w.no_work_order FROM work_order w LEFT JOIN pembayaran p ON p.no_work_order=w.no_work_order WHERE w.kode_cabang='CBG001' AND COALESCE(p.status_pembayaran,'BELUM_LUNAS')<>'LUNAS' AND NOT EXISTS (SELECT 1 FROM work_order_korporat k WHERE k.no_work_order=w.no_work_order) ORDER BY w.no_work_order LIMIT 1");
 $s->test('WO belum lunas tidak diberi judul bukti pembayaran',function()use($s,$unpaid){ksAssert($unpaid!=='');$r=$s->c('cash1')->get('panel/pembayaran.php?lihat='.rawurlencode($unpaid));$s->ok($r);preg_match('~<title>(.*?)</title>~s',$r['body'],$m);ksAssert(str_contains($m[1]??'','Rincian Tagihan Servis')&&!str_contains($m[1],'Bukti Pembayaran'));});
 foreach(['BELUM_LUNAS'=>'Tagihan Servis Korporat','LUNAS'=>'Bukti Pelunasan Korporat'] as $status=>$title)$s->test('Dokumen korporat '.$status,function()use($s,$status,$title){$id=(string)ksOne($s->db,'SELECT id_tagihan FROM tagihan_korporat WHERE status_pembayaran=? ORDER BY id_tagihan LIMIT 1',[$status]);if($id===''&&$status==='BELUM_LUNAS')$id=ksCetakInvoiceFixture($s);ksAssert($id!=='','Fixture tagihan tidak tersedia');$r=$s->c('owner')->get('panel/tagihan_korporat.php?lihat='.$id);$s->ok($r);preg_match('~<title>(.*?)</title>~s',$r['body'],$m);ksAssert(str_contains($m[1]??'',$title)&&str_contains($m[1],'Tagihan-'.$id));ksAssert(str_contains($r['body'],'Jumlah WO')&&str_contains($r['body'],'<dt>Periode</dt>'));});
 $s->test('Rincian servis menggunakan judul dan referensi WO',function()use($s,$paid){$r=$s->c('audit')->get('panel/rincian_servis.php?wo='.rawurlencode($paid));$s->ok($r);preg_match('~<title>(.*?)</title>~s',$r['body'],$m);ksAssert(str_contains($m[1]??'','Rincian Servis Kendaraan')&&str_contains($m[1],$paid));});
 $s->test('Rincian Gudang tetap tidak memuat kolom harga',function()use($s,$paid){$r=$s->c('stock1')->get('panel/rincian_servis.php?wo='.rawurlencode($paid));$s->ok($r);ksAssert(str_contains($r['body'],'Rincian Servis Kendaraan')&&!str_contains($r['body'],'Harga satuan')&&!str_contains($r['body'],'Total tercatat'));});
 $s->test('Audit memiliki judul khusus dan peringatan halaman aktif',function()use($s){$r=$s->c('audit')->get('panel/audit.php?hal_transaksi=2');$s->ok($r);ksAssert(str_contains($r['body'],'Laporan Jejak Audit Operasional')&&str_contains($r['body'],'Setiap daftar mencetak halaman yang sedang dibuka'));});
 $s->test('Rincian terlarang tidak membocorkan kop cabang lain',function()use($s,$paid){$r=$s->c('stock2')->get('panel/rincian_servis.php?wo='.rawurlencode($paid));$s->ok($r,404);ksAssert(!str_contains($r['body'],'class="ks-cetak-kop"'));});
 $s->test('Filter nomor polisi tetap di-escape pada metadata cetak',function()use($s,$periode){$r=$s->c('owner')->get('panel/laporan.php?jenis=riwayat&no_polisi='.rawurlencode('<b>ABC</b>').'&'.$periode);$s->ok($r);ksAssert(str_contains($r['body'],'&lt;b&gt;ABC&lt;/b&gt;')&&!str_contains($r['body'],'<dd><b>ABC</b>'));});
 $s->test('Kop memakai alamat cabang nyata dari database',function()use($s,$periode){$c=$s->db->query("SELECT alamat FROM cabang WHERE kode_cabang='CBG001'")->fetchColumn();$r=$s->c('admin1')->get('panel/laporan.php?jenis=stok&'.$periode);ksAssert(str_contains($r['body'],htmlspecialchars((string)$c,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8')));});
 $before=ksDigests($s->db,(string)ksOne($s->db,'SELECT DATABASE()'));
 $s->test('Menyiapkan dokumen cetak tidak mengubah tabel',function()use($s,$before,$periode,$paid){$s->c('owner')->get('panel/laporan.php?jenis=riwayat&'.$periode);$s->c('audit')->get('panel/audit.php');$s->c('cash1')->get('panel/pembayaran.php?lihat='.rawurlencode($paid));ksAssert(ksDigests($s->db,(string)ksOne($s->db,'SELECT DATABASE()'))===$before);});
}

/** Make an actual unpaid collective invoice in the disposable test database only. */
function ksCetakInvoiceFixture(KsSuite $s):string{
 $owner=$s->c('owner');$id='CP-'.$s->tag;$data=ksCustomerData($id,'Perusahaan Contoh Cetak '.$s->tag);$data['jenis_identitas']='NIB';$data['nama_pic']='PIC Cetak';
 $s->ok($owner->submit('panel/pelanggan.php?tipe=korporat',['aksi'=>'tambah'],$data));
 $today=(string)ksOne($s->db,'SELECT CURDATE()');$start=(new DateTimeImmutable($today))->modify('first day of last month')->format('Y-m-d');$end=(new DateTimeImmutable($today))->modify('last day of this month')->format('Y-m-d');$month=substr($start,0,7);
 $s->ok($owner->submit('panel/kontrak_korporat.php?id='.$id,['@field'=>'plafon_kredit'],['berlaku_mulai'=>$start,'berlaku_sampai'=>$end,'plafon_kredit'=>'1000000']));
 $motor=ksMotorData($s->tag,'CP');$s->ok($owner->submit('panel/motor.php',['aksi'=>'tambah'],$motor));$s->ok($owner->submit('panel/motor.php?pilih='.rawurlencode($motor['no_polisi']),['aksi'=>'tetapkan_pemilik'],['id_pelanggan'=>$id,'tanggal_mulai'=>$start]));
 $contract=ksOne($s->db,'SELECT id_kontrak FROM kontrak_korporat WHERE id_pelanggan=?',[$id]);
 foreach(['CBG001'=>'tech1','CBG002'=>'tech2'] as $i=>$mechanic){$wo='CP-'.$s->tag.'-'.substr($i,-1);ksExec($s->db,"INSERT INTO work_order(no_work_order,tanggal_masuk,tanggal_selesai,kode_cabang,id_pelanggan,no_polisi,id_mekanik_pj,keluhan,estimasi_biaya,status_pekerjaan) VALUES (?,?,?,?,?,?,?,'Fixture cetak tagihan belum lunas',0,'SELESAI')",[$wo,$start.' 09:00:00',$start.' 10:00:00',$i,$id,$motor['no_polisi'],$s->accounts[$mechanic]['staff']]);ksExec($s->db,'INSERT INTO work_order_korporat(no_work_order,id_pelanggan,id_kontrak) VALUES (?,?,?)',[$wo,$id,$contract]);ksExec($s->db,'INSERT INTO detail_wo_jasa(no_work_order,kode_jasa,biaya) VALUES (?,?,10000)',[$wo,$s->data['jasa']]);}
 $s->ok($owner->submit('panel/tagihan_korporat.php?id='.$id.'&bulan='.$month,['aksi'=>'terbitkan']));$invoice=(string)ksOne($s->db,'SELECT id_tagihan FROM tagihan_korporat WHERE id_pelanggan=? AND periode=?',[$id,$start]);ksAssert($invoice!=='');return $invoice;
}
